using BusinessPartnerPortal.Api.Domain;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Data;
public static class Bootstrapper{public static async Task EnsureUsersAsync(IServiceProvider services,IConfiguration config,ILogger logger){using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var hasher=new PasswordHasher<User>();await EnsureUser(db,hasher,config["ADMIN_EMAIL"],config["ADMIN_PASSWORD"],config["ADMIN_NAME"]??"Portal Administrator","ADMIN","ADMIN",logger);await EnsureUser(db,hasher,config["INTERNAL_EMAIL"],config["INTERNAL_PASSWORD"],config["INTERNAL_NAME"]??"Internal User","INTERNAL","SUPPLY_CHAIN",logger);}
 static async Task<User?> EnsureUser(AppDbContext db,PasswordHasher<User> hasher,string? email,string? password,string name,string userType,string roleCode,ILogger logger){if(string.IsNullOrWhiteSpace(email)||string.IsNullOrWhiteSpace(password)){logger.LogWarning("Bootstrap credentials for {UserType} are not configured.",userType);return null;}var normalized=email.Trim().ToLowerInvariant();var user=await db.Users.FirstOrDefaultAsync(x=>x.Email.ToLower()==normalized);if(user is null){user=new User{Id=Guid.NewGuid(),Email=normalized,FullName=name,UserType=userType,IsSuperAdmin=userType=="ADMIN",IsActive=true,CreatedAt=DateTimeOffset.UtcNow,UpdatedAt=DateTimeOffset.UtcNow};user.PasswordHash=hasher.HashPassword(user,password);db.Users.Add(user);await db.SaveChangesAsync();}var role=await db.Roles.FirstOrDefaultAsync(x=>x.Code==roleCode);if(role is not null&&!await db.UserRoles.AnyAsync(x=>x.UserId==user.Id&&x.RoleId==role.Id)){db.UserRoles.Add(new UserRole{UserId=user.Id,RoleId=role.Id});await db.SaveChangesAsync();}return user;}}
